import{j as e}from"./vendor-DMfPVYRw.js";import{U as b,V as E,E as R,b as k,z as T,G as q}from"./index-DO0CKTM2.js";import{c as I}from"./references-BrGI0Vp9.js";const g={benign:"Benign / expected",suspicious:"Suspicious / escalate",malicious:"Confirmed malicious",insufficient:"Insufficient evidence"},y={close:"Close with documented rationale",investigate:"Collect more evidence",escalate:"Escalate to Tier 2 / incident response",contain:"Request proportionate containment"},_="2026-10-23",H={...Object.fromEntries(Object.values(I).map(i=>[i.id,{title:i.title,url:i.url,scope:i.scope}])),taskAudit:{title:"Windows Security event 4698",url:"https://learn.microsoft.com/en-us/windows/security/threat-protection/auditing/event-4698",scope:"Task creation event, SubjectUserName, Computer, TaskName and TaskContent; normalised task action extract."},filterPolicy:{title:"Exchange hosted content filter policy",url:"https://learn.microsoft.com/en-us/powershell/module/exchangepowershell/set-hostedcontentfilterpolicy?view=exchange-ps",scope:"AllowedSenderDomains policy parameter; an allow-list modification does not establish a particular message's complete filtering path."},signin:{title:"Microsoft Entra sign-in logs",url:"https://learn.microsoft.com/en-us/entra/identity/monitoring-health/concept-sign-ins",scope:"Sign-in events and context; IP location alone is not attribution."},process:{title:"DeviceProcessEvents",url:"https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-deviceprocessevents-table",scope:"Endpoint process fields and timestamps; selected training extracts."},network:{title:"DeviceNetworkEvents",url:"https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-devicenetworkevents-table",scope:"Device, initiating process and network correlation fields."},task:{title:"MITRE ATT&CK scheduled task",url:"https://attack.mitre.org/techniques/T1053/005/",scope:"Scheduled tasks can support recurring execution; a task alone is not proof of malware."},evasion:{title:"MITRE ATT&CK disable or modify tools",url:"https://attack.mitre.org/techniques/T1685/",scope:"Security-control impairment as a technique; corroborate actual success."},av:{title:"Defender Antivirus event reference",url:"https://learn.microsoft.com/en-us/defender-endpoint/troubleshoot-microsoft-defender-antivirus",scope:"5001 real-time protection disabled; 5000 enabled; 5007 configuration change."},snowLogin:{title:"Snowflake LOGIN_HISTORY",url:"https://docs.snowflake.com/en/sql-reference/account-usage/login_history",scope:"EVENT_ID, EVENT_TIMESTAMP, USER_NAME, CLIENT_IP and authentication outcome."},snowQuery:{title:"Snowflake QUERY_HISTORY",url:"https://docs.snowflake.com/en/sql-reference/account-usage/query_history",scope:"QUERY_ID, AUTHN_EVENT_ID, SESSION_ID, USER_NAME and result volume; result bytes are not proof of exfiltration."},snowAccess:{title:"Snowflake ACCESS_HISTORY",url:"https://docs.snowflake.com/en/sql-reference/account-usage/access_history",scope:"Object access and QUERY_ID correlation; Enterprise Edition or higher, coverage/latency limitations."},m365:{title:"Microsoft 365 audited activities",url:"https://learn.microsoft.com/en-us/purview/audit-log-activities",scope:"Exchange administration operations and audit record context."},pim:{title:"PIM role audit history",url:"https://learn.microsoft.com/en-us/entra/id-governance/privileged-identity-management/pim-how-to-use-audit-log",scope:"Activation lifecycle and correlation; activation alone does not imply abuse."},deviceCode:{title:"Microsoft identity device authorization grant",url:"https://learn.microsoft.com/en-us/entra/identity-platform/v2-oauth2-device-code",scope:"Device authorization is legitimate OAuth; investigate possible social engineering separately."},traversal:{title:"OWASP path traversal",url:"https://owasp.org/www-community/attacks/Path_Traversal",scope:"Traversal attempts versus successful access outside an allowed root."},phishing:{title:"MITRE ATT&CK phishing",url:"https://attack.mitre.org/techniques/T1566/",scope:"Campaign correlation; delivery, clicks and compromise are separate observations."},email:{title:"Defender EmailEvents",url:"https://learn.microsoft.com/en-us/defender-xdr/advanced-hunting-emailevents-table",scope:"NetworkMessageId, recipient, sender, delivery and threat fields."},discovery:{title:"MITRE ATT&CK network service discovery",url:"https://attack.mitre.org/techniques/T1046/",scope:"Network scanning is dual use and requires authorisation/scope checks."},exposure:{title:"Microsoft exposed credentials investigation",url:"https://learn.microsoft.com/en-us/entra/id-protection/concept-identity-protection-risks",scope:"Leaked credential risk signals require investigation; this scenario's supplier report is an unverified synthetic claim, not an Entra detection."}},w={"SOC-301":{focus:["Repudiated access and an unauthorised forwarding rule corroborate account compromise; endpoint scope remains uncertain.","A shared UPN means both products use the same raw device ID.","The 72 KB connection proves the entire mailbox was stolen.","PowerShell alone establishes a malicious payload."],next:["Preserve the correlated session, process and mailbox records and coordinate targeted response.","Wait for an attachment hash before escalating the repudiated rule.","Attribute every event sharing the address to one human operator.","Close because workstation maintenance was approved yesterday."],story:"On 21 October 2026, failures from 198.51.100.31 preceded a successful nora@lumen.example sign-in at 09:03. At 09:12, winword.exe launched powershell.exe on LM-WS-031.lumen.example; host-scoped PID 4310 was linked to traffic at 09:13. A forwarding rule was created at 09:16. The 09:25 trusted callback recorded Nora’s denial of the session and rule and corroborated the mapping between separate Entra and Defender identifiers. Traffic volume does not establish its contents.",necessary:"Preserve the correlated evidence and escalate repudiated account access and the rule.",optional:"Scope related devices and sessions and obtain attachment/network analysis.",approval:"Authorised responders must coordinate session and credential controls, rule removal and any impact-assessed workstation isolation.",excessive:"Isolating every host or claiming confirmed mailbox theft from traffic volume is unsupported."},"SOC-302":{focus:["The three sessions match a verified corporate VPN pilot within the reviewed window.","NL geolocation proves all three users physically travelled.","Satisfied MFA alone establishes that every session was authorised.","A shared source proves a password-spray attack."],next:["Document the pilot, known-device and follow-up evidence before scoped benign closure.","Reset all three passwords because of the country label.","Suppress the source address indefinitely for every user.","Treat the 09:20 follow-up as proof that all later activity is benign."],story:"On 21 October 2026 at 08:50, inventory recorded approved VPN egress 192.0.2.62 for the named pilot. The 09:05 extract showed eli@lumen.example, sam@lumen.example and leah@lumen.example using it on known compliant devices. The 09:20 follow-up found no listed role, authentication-method or unfamiliar-application changes within its bounded coverage. IP-derived NL location has a documented network explanation; it does not establish physical travel.",necessary:"Close with the verified pilot, session and bounded follow-up evidence.",optional:"Improve alert context with an owned, expiring egress exception and monitoring.",approval:"Detection tuning requires normal owner/change review.",excessive:"Blanket password resets or permanent global source suppression are disproportionate."},"SOC-303":{focus:["An unapproved recurring task is suspicious, but no binary malware verdict is supplied.","The updater-like name establishes approved deployment.","The process-linked connection proves command and control.","Absence from inventory alone confirms malicious binary content."],next:["Preserve task XML and sample identity, then obtain authorised analysis and escalate.","Delete the task and executable before collecting their identities.","Close because taskeng.exe can run legitimate tasks.","Declare credential theft from the 6 KB connection."],story:"On 21 October 2026 at 09:14, event 4698 recorded task \\LumenUpdate on LM-WS-033.lumen.example with an action in a directory writable by marin. Matching execution followed at 09:15 and a host-scoped process connection at 09:16. At 09:30, marin@lumen.example denied installing the helper and inventory showed no matching approved package or task. This establishes suspicious recurring execution, while binary contents and connection purpose remain unverified.",necessary:"Preserve task, process and sample identity and obtain prompt responder analysis.",optional:"Consider targeted task disabling or isolation if analysis or continued activity increases risk.",approval:"Acquisition, task changes and isolation require authorised responders and evidence preservation.",excessive:"Deleting evidence or isolating unrelated hosts is not justified."},"SOC-304":{focus:["Malicious sample analysis and continuing protection loss support targeted containment.","Event 5001 identifies the shell as the setting-change actor.","Four MB outbound proves four MB of stolen documents.","No identity role changes excludes token misuse."],next:["Request authorised endpoint isolation, preserve evidence and investigate the telemetry gap.","Close because a known managed session was used.","Declare the setting-change actor proven by timing alone.","Restore protection without preserving the malicious lineage."],story:"On 21 October 2026 at 09:05, isa@lumen.example used the known managed session. Office-associated shell execution followed at 09:06 on LM-WS-034.lumen.example. Configuration change at 09:07 preceded actual protection disablement at 09:08 and process-linked traffic at 09:09. At 09:20, the supplied IR analysis confirmed malicious content associated with PID 3400 and protection remained disabled. The 09:10–09:18 telemetry gap limits reconstruction; the control event does not independently identify its actor.",necessary:"Escalate confirmed malicious activity and ongoing protection loss; preserve available evidence.",optional:"Hunt related endpoint lineage and review the user session before selecting identity controls.",approval:"Targeted isolation, eradication and verified protection restoration belong to authorised responders.",excessive:"Claiming stolen content or attributing the setting change from proximity alone exceeds the evidence."},"SOC-305":{focus:["An anonymising-address label warrants investigation but does not establish compromise.","An existing MFA claim proves a fresh user-approved challenge.","The feed label identifies the human attacker.","No role change proves the session benign."],next:["Validate feed recency, obtain trusted owner confirmation and collect resource activity.","Close because the fifteen-minute role review was clean.","Reset all accounts using anonymising infrastructure.","Treat absent device context as confirmed malicious hardware."],story:"On 21 October 2026 at 09:00, the supplied reputation snapshot labelled 192.0.2.105 as anonymising egress and noted an earlier verification date. At 09:10, teo@lumen.example authenticated with unknown device context and an existing MFA claim. The 09:25 review found no role or authentication-method changes within 09:10–09:25, but resource evidence was absent and trusted owner contact had not succeeded. Competing explanations remain unresolved.",necessary:"Continue prompt identity/resource investigation and validate reputation context.",optional:"Escalate if risk increases or the owner denies the session.",approval:"Session and credential controls need corroboration and the authorised identity process.",excessive:"Blanket suspension solely because of a reputation label is disproportionate."},"SOC-306":{focus:["AUTHN_EVENT_ID links the login and query, but result bytes do not establish client download.","A shared username alone identifies which login executed the query.","A 24 MB query result is confirmed external disclosure.","A missing MFA field proves no second factor was used."],next:["Preserve joined records, obtain client/egress context and recollect after expected view latency.","Close because no COPY command appears in delayed extracts.","Report confirmed customer disclosure based on result size.","Disable every reporting account without dependency review."],story:"On 21 October 2026 at 09:01, SVC_REPORTS logged in from unfamiliar source 198.51.100.66 as event 8306. At 09:12, syn-query-306 referenced AUTHN_EVENT_ID 8306 and produced 120,000 rows and a 24 MB result; object access identified LUMEN_ANALYTICS.CURATED.CUSTOMER_EXPORT. At 09:30 the owner denied approval for the source or query. The 10:00 manifest documented earlier coverage cutoffs for delayed views. Neither complete client receipt nor external dissemination is established.",necessary:"Preserve authentication/query/object correlation and escalate potential exposure with the data owner.",optional:"Recover client/session/egress evidence and recollect delayed views with appropriate permissions.",approval:"Session termination or service-credential rotation requires dependency-aware owner coordination.",excessive:"Disabling all reporting accounts or claiming exfiltration from result bytes is unsupported."},"SOC-307":{focus:["Administrator repudiation corroborates unauthorised allow-list tampering; recipient compromise is unproven.","Adding one sender domain means all filtering was disabled.","Delivery of the phishing message proves recipient takeover.","The policy name establishes change approval."],next:["Preserve the policy snapshot and request scoped session/policy response with authorised owners.","Reset every recipient solely because a message was delivered.","Conclude the policy change caused delivery without evaluation evidence.","Close because the audit operation returned success."],story:"On 21 October 2026, ops-admin@lumen.example signed in at 09:05 from 203.0.113.77. At 09:11, the session added bulletin-review.example to Inbound-Standard AllowedSenderDomains. A related phishing message was delivered at 09:22. During the trusted 09:28 callback, the administrator denied the session and change. The privileged modification is corroborated as unauthorised, while causal policy evaluation, clicks and later recipient activity are incomplete.",necessary:"Preserve policy/admin/session evidence and escalate the unauthorised change.",optional:"Scope other changes and investigate matching messages, clicks and later sessions.",approval:"Policy rollback, identity controls and quarantine require the authorised identity/mail/change owners.",excessive:"Suspending every recipient or asserting causal bypass and takeover from delivery alone is unsupported."},"SOC-308":{focus:["Verified approval, scoped use and scheduled expiry explain this PIM activation.","An out-of-hours activation is necessarily malicious.","Expiry deletes the eligible assignment.","Step-up authentication alone authorises every later action."],next:["Close within scope using approval, role-use and expiry evidence; retain review of future changes.","Remove all eligible roles because an activation was out of hours.","Suppress all future PIM activation alerts.","Describe expiry as permanent eligibility removal."],story:"On 21 October 2026 at 08:55, the trusted emergency change authorised devon@lumen.example to repair one role assignment. PIM activation completed at 09:02 with required approval and authentication. The 09:10 repair matched the change, and the active assignment expired at 09:32. Eligibility remained. The 09:00–09:40 audit scope supports expected just-in-time work without establishing later access.",necessary:"Close with correlated approval, scoped action and expiry evidence.",optional:"Maintain eligibility reviews and emergency-change alert context.",approval:"Eligibility removal or detection tuning requires the governance/change owner.",excessive:"Disabling the administrator or suppressing all activations is disproportionate."},"SOC-309":{focus:["A four-minute protection gap is observed, but its actor and cause are unknown.","Event 5007 supplies changed settings and actor identity.","Recovery proves the disablement was approved maintenance.","No malware events during reduced protection excludes compromise."],next:["Verify current protection and retrieve actor/configuration, maintenance and gap-activity evidence.","Close immediately because event 5000 reports recovery.","Declare the user malicious based only on event 5001.","Reset all workstation accounts without identity evidence."],story:"On 21 October 2026 at 09:09, LM-WS-039.lumen.example recorded event 5007 without old/new settings or an actor. Event 5001 reported protection disabled at 09:10, followed by event 5000 reporting re-enablement at 09:14. The observed gap was four minutes. Process, network, change approval and owner evidence were absent, so neither malicious tampering nor legitimate maintenance was established.",necessary:"Verify protection health and investigate configuration, actor, maintenance and gap activity.",optional:"Escalate an unexplained or repeated gap and collect process/network corroboration.",approval:"Isolation is conditional on corroborated compromise or continuing control loss and responder authority.",excessive:"Blanket resets or a confirmed-malware verdict from this single source are unsupported."},"SOC-310":{focus:["The unsolicited code workflow and repudiated helpdesk context support suspected phishing; token scope is incomplete.","A legitimate Microsoft page proves the request legitimate.","Device-code authentication is inherently malicious.","Mailbox listing proves a complete export."],next:["Preserve lure/session evidence and request authorised token/session response while scoping access.","Reset the password and assume all tokens are revoked.","Disable all device-code flows without impact review.","Close because no endpoint execution is supplied."],story:"On 21 October 2026, alix@lumen.example reported a lure at 09:08 and code entry on a legitimate Microsoft page at 09:11. A successful device-code sign-in followed at 09:12 and session-associated mailbox listing at 09:15. The trusted 09:18 interview described no user-initiated setup, and helpdesk verification at 09:25 denied the lure. This supports social engineering while leaving exact token scope and content access unresolved.",necessary:"Escalate promptly, preserve evidence and request affected-token/session response.",optional:"Review flow restrictions and provide focused user guidance.",approval:"Identity responders execute and verify revocation; broader restrictions require administrator impact review.",excessive:"Assuming password theft, complete export or endpoint compromise exceeds the evidence."},"SOC-311":{focus:["The supplier claim lacks provenance and current-secret validation; short-window normal sign-ins do not disprove exposure.","The collection label proves a reusable password exists.","The active directory identity establishes the claimed record’s age.","Two known sign-ins prove no exposure ever occurred."],next:["Request lawful redacted provenance and broaden identity-risk review without obtaining secrets.","Test an alleged leaked password by signing into the account.","Browse the claimed illicit source as a learner task.","Close solely because the current short window is normal."],story:"On 21 October 2026 at 09:00, the fictional supplier named joren@lumen.example without a password, independent provenance or known record age. The 09:10 directory snapshot distinguished the current account from an unassigned old alias. The 09:20 extract showed known-device sign-ins in a short window. Follow-up at 09:35 still had not established authenticity or a current secret. Controlled verification is needed before either compromise or false-positive closure.",necessary:"Seek lawful minimal provenance and identity-owner validation, retaining uncertainty.",optional:"Review broader sign-in/risk signals and involve appropriate specialists.",approval:"Credential/session controls need verified exposure or suspicious use under the identity procedure; privacy handling belongs to authorised roles.",excessive:"Using alleged secrets to log in or contacting illicit sellers is outside the exercise."},"SOC-312":{focus:["Gateway records show blocked traversal-shaped attempts, not verified disclosure.","A 403 proves no previous or direct-origin access occurred.","The unrelated welcome.pdf 200 response proves traversal success.","Encoded input alone proves server execution."],next:["Retain request IDs and raw/decoded paths and obtain application/origin evidence.","Declare file theft from blocked gateway records.","Treat normal response bytes as stolen secrets.","Isolate the server solely because the pattern matched."],story:"On 21 October 2026 at 09:01 and 09:02, portal.lumen.example received traversal-shaped requests from 203.0.113.112. Both were blocked with 403 responses and no upstream application request ID. At 09:04, another source requested welcome.pdf and received 200; that comparison does not establish success for the earlier inputs. Gateway-only 09:00–09:10 coverage does not assess prior or direct-origin access.",necessary:"Preserve gateway requests and obtain application/origin evidence to validate exposure.",optional:"Maintain scoped protection and review resolved-path validation with the owner.",approval:"Application fixes and service disruption require the approved owner/change process.",excessive:"Server isolation or confirmed-theft claims solely from blocked requests are disproportionate."},"SOC-313":{focus:["The campaign is confirmed phishing; delivered, clicked and blocked recipients have different observed risk.","All three recipients received the message.","Eli’s click proves credential submission.","Leah’s missing click record proves interaction was impossible."],next:["Contain the lure through the mail team, contact the clicked user and scope later access.","Reset every targeted user solely because one clicked.","Treat the blocked recipient as proven account compromise.","Close because short-window sign-ins show no unfamiliar success."],story:"On 21 October 2026 at 09:03, messages from review@document-check.example were delivered to Eli and Leah but blocked for Sam. Eli reached the credential-form landing page at 09:07; no submission was recorded. At 09:20, the mail team confirmed a credential-harvesting lure and the business owner denied the domain. The later identity extract showed a known-device Eli session and no unfamiliar success in its bounded window. Credential entry and later misuse remain unresolved.",necessary:"Preserve campaign/message IDs, scope recipients and request authorised lure containment.",optional:"Contact the clicked user, investigate session/resource activity and provide safe internal guidance.",approval:"Quarantine/blocking and evidence-supported identity controls require authorised mail/identity teams.",excessive:"Resetting every targeted account or claiming takeover from delivery/blocking alone is unsupported."},"SOC-314":{focus:["Operator, host, range and execution interval match independently verified inventory approval.","The utility filename alone proves benign intent.","A signed-program label excludes malicious use.","Many destinations alone prove lateral movement."],next:["Close within verified change scope and retain detection for out-of-scope discovery.","Permanently allow-list the filename across all hosts.","Isolate the workstation despite matching approval.","Treat bundled negative findings as complete later authentication history."],story:"On 21 October 2026 at 08:55, SYN-CHG-314 authorised nia@lumen.example on LM-OPS-044.lumen.example to inventory 192.0.2.144–192.0.2.159 during 09:00–09:30. The tool started at 09:05 and host-scoped PID 4400 contacted the approved targets during 09:06–09:12. Completion and operator confirmation were recorded at 09:12. Independent approval, rather than the tool name, supports scoped benign closure.",necessary:"Close with scoped approval, process, target-range and completion evidence.",optional:"Keep narrow operator/host/range/window exceptions and review future deviations.",approval:"Detection exceptions require the relevant owner’s scoped approval.",excessive:"Globally trusting the utility or isolating the operator despite this context is disproportionate."},"CYSA-401":{focus:["Failures, a linked success and a user dispute warrant escalation; application access is unproven.","One failure per account excludes a credential-attack pattern.","Successful authentication proves a payables export.","A shared source proves the attacker’s physical identity."],next:["Preserve AQ-S19, coordinate proportionate identity response and recover application records.","Close because missing audit contains no export.","Report disclosure from group membership alone.","Assume a password reset ends every token."],story:"On 23 October 2026, 198.51.100.41 failed once against each of 46 accounts during 08:06–08:10. nqadir authenticated successfully as AQ-S19 at 08:13. Inventory at 08:16 showed payables access capability, and the trusted 08:24 callback recorded the user’s denial. The 08:27 health record identified an application-audit gap from 08:00 to 08:22. Capability and successful login do not establish reads or exports.",necessary:"Preserve gateway/session evidence and escalate disputed access with the collection gap explicit.",optional:"Recover application-side evidence and scope related accounts.",approval:"Authorised identity responders assess, execute and verify affected-session/access controls.",excessive:"Claiming application exfiltration or universal token revocation from a password reset is unsupported."},"CYSA-402":{focus:["Sample analysis and recurring unauthorised execution establish malicious activity, but transmission is unobserved.","An updater-like name proves approved software.","Absent network collection proves no transfer occurred.","A writable directory alone proves credential transmission."],next:["Preserve task/sample/process identity and request authorised isolation and exposure scoping.","Delete the sample before retaining its identity.","Wait for an outbound destination before addressing confirmed malicious execution.","Treat every peer build host as compromised without scoping."],story:"On 23 October 2026 at 09:02, buildsvc launched the cache executable on BS-BUILD-3. The 09:04 task used the same path and repeated at logon; a matching launch followed at 09:08. At 09:16, supplied analysis confirmed a credential-collection routine and task registration in SAMPLE-BS-77. The owner denied approval at 09:22. Network collection was absent, so malicious recurring execution is confirmed without proof of outbound transfer.",necessary:"Preserve persistence/sample identity and request targeted containment of confirmed malicious execution.",optional:"Scope buildsvc access, secret exposure and peer systems according to subsequent evidence.",approval:"BS-IR must authorise and verify isolation, removal and safe release.",excessive:"Deleting persistence evidence or asserting unobserved destinations/peer compromise exceeds the record."},"CYSA-403":{focus:["Application and response correlation confirm outside-root disclosure for CL-R91.","The earlier 403 proves every later request was blocked.","A 200 response alone identifies file contents.","The file read establishes remote code execution."],next:["Preserve CL-R91 correlation and request emergency route restriction and resolved-path validation.","Treat denied CL-R88 as proof CL-R91 could not succeed.","Reset every user because service.conf necessarily contains passwords.","Close after blocking only the observed encoding."],story:"On 23 October 2026 at 10:02, CL-R88 from 203.0.113.63 received 403. At 10:05, CL-R91 received 200 and its application audit recorded an outside-root read of /srv/private/service.conf under cl-web. The 10:06 response audit confirmed that the same request returned those 640 bytes contrary to policy. At 10:13, the owner identified emergency route restriction and encoded/relative-path validation. Secret contents and host execution were not supplied.",necessary:"Preserve request/read/response correlation and escalate confirmed disclosure for route treatment.",optional:"Scope other requests and determine the file’s actual sensitivity.",approval:"Emergency restriction and code/access fixes require the approved service-owner change process.",excessive:"Declaring stolen passwords or remote code execution from this read is unsupported."},"CYSA-404":{focus:["Verified package, configuration and rollout explain the observed periodic flows.","Sixty-second periodicity alone establishes command and control.","A known destination makes every executable benign.","A heartbeat description proves TLS could never carry other content."],next:["Document scoped closure and, if approved, tune only tested package/destination/host conditions.","Suppress every future connection to the domain.","Isolate the workstation based only on periodicity.","Describe unavailable TLS content as proven harmless."],story:"On 23 October 2026, DT-DESIGN-4 contacted sync.dovetail.example every 60 seconds during 08:01–08:31. Endpoint correlation at 08:32 tied the sessions to DT-P12 and an approved digest. Configuration at 08:34 matched the interval/destination, while the 08:35 change record documented the 07:55 rollout. The 08:40 trial retained alerts for an unapproved executable. TLS content was unavailable, but corroborated context explains this alert.",necessary:"Close this alert with package/configuration/change evidence and a bounded conclusion.",optional:"Monitor configuration changes and submit the tested narrow exception if needed.",approval:"Tuning needs owner review, controlled deployment and retained monitoring.",excessive:"Global destination allow-listing or isolation solely for periodicity is disproportionate."},"CYSA-405":{focus:["Verified unauthorised forwarding confirms malicious mailbox activity; transferred content is unknown.","Delivery of EF-M52 alone proves takeover.","The user statement proves the exact token-acquisition path.","Rule creation proves every later message was exported."],next:["Preserve EF-S6 and rule evidence, request authorised response and obtain mail-flow scope.","Assume changing the password revokes every token.","Report all historic mail stolen without mail-flow evidence.","Close because IP alone cannot identify an operator."],story:"On 23 October 2026 at 09:10, EF-M52 was delivered to tmarin. In the 09:18 callback, the user reported password entry at about 09:13 and denied forwarding-rule creation. EF-S6 authenticated at 09:16 and created EF-ForwardAll at 09:19, targeting ledger-drop@parcel-notices.example. At 09:24, the owner verified the rule/destination as unauthorised. Malicious mailbox activity is corroborated; actual forwarded messages and the exact credential/token path need further evidence.",necessary:"Preserve message/session/rule evidence and escalate the confirmed unauthorised action.",optional:"Investigate other rules, access paths and mail flow to establish impact.",approval:"EF-IR and identity/mail owners authorise and verify session/rule containment and credential controls.",excessive:"Claiming all mail stolen or universal token revocation from password reset exceeds the record."},"CYSA-406":{focus:["FR-ID-1 has higher contextual urgency despite the lab’s higher Base score; local intrusion is not shown.","The 9.8 finding always takes priority regardless of context.","Exploitation elsewhere proves this local service was compromised.","Installer success alone closes a running-service finding."],next:["Use FR-CH6 with staging/rollback, verify effective state and retain an owned lab finding.","Ignore the lab finding permanently because inbound access is restricted.","Declare local exploitation from the advisory alone.","Close when package installation reports success."],story:"On 23 October 2026 at 10:10, assessment confirmed the affected reachable FR-ID-1 component. The 10:14 advisory described exploitation elsewhere and a validated update. At 10:16, higher-scored FR-LAB-9 had verified restricted access. The 10:21 register distinguished critical identity-service impact from disposable lab data and identified approved FR-CH6. The 10:25 plan required effective-version and route verification after reload. Emergency treatment is justified without declaring local intrusion.",necessary:"Coordinate FR-CH6 and verify effective running version/route; retain tracked lab treatment.",optional:"Reassess lab risk if access/threat context changes and investigate new intrusion indicators.",approval:"Updates, reload and rollback follow the approved service-owner change plan.",excessive:"Declaring compromise from an advisory or abandoning lab ownership is unsupported."},"CYSA-407":{focus:["Verified package and approved job support closure; the tuning revision is not yet deployed.","The filename alone proves benign activity.","Candidate tests prove the production rule has changed.","The approved account can be suppressed globally."],next:["Retain package/change/job evidence and submit benign and unauthorised tests for controlled tuning.","Report GN-R4 as already deployed.","Exclude every event with the process name.","Disable collection to reduce alerts."],story:"On 23 October 2026 at 11:01, GN-R4 alerted on inventory.exe under gn-inventory on GN-WKS-12. Identity at 11:04 and job/change records at 11:06 corroborated expected read-only enumeration. At 11:12, candidate tests retained alerts for another digest and out-of-job execution. The 11:16 plan explicitly said the revision was not deployed. Case closure and approval/deployment of a detection change are separate decisions.",necessary:"Close with verified package/change/job evidence and explicit tuning state.",optional:"Submit the narrow revision and both test outcomes; monitor after approved deployment.",approval:"GN-DET owns review, rollback and effective-deployment validation.",excessive:"Global filename/account suppression or reporting a candidate as deployed is unsupported."},"CYSA-408":{focus:["An export discrepancy warrants owned investigation, but the TLS session is not linked to the job.","Proximity proves HC-J72 was externally transferred.","The 1.4 MB volume identifies the export recipient.","The 09:00 handover proves completed containment."],next:["Hand over to HC-IR-2 with source-linked times, the transfer gap and explicit next decisions.","Mark contained because another responder accepted ownership.","Declare disclosure from export completion and nearby traffic.","Close because HC-CH9 exists despite a scope mismatch."],story:"On 23 October 2026 at 08:42, hc-report completed HC-J72 on HC-APP-5 for 420 records. At 08:44, a TLS session sent 1.4 MB, with no process/content or request correlation linking it to the export. The 08:49 change review described 300 records and a different destination, with authorisation unresolved. At 08:53, health records identified a download-audit gap covering the window. HC-IR-2 accepted escalation at 09:00 with containment still pending. Continued investigation is needed before a disclosure verdict.",necessary:"Preserve and hand over the UTC chronology, collection gap, accepted owner and outstanding questions.",optional:"Recover transfer evidence and obtain owner confirmation of expanded scope.",approval:"HC-IR-2 and the service owner assess and verify controls; notification decisions belong to authorised roles if impact is established.",excessive:"Treating escalation acceptance as containment, or proximity as transfer proof, is unsupported."}},j